// Normalize Remotive API response into common shape
const jobs = $input.first().body.jobs || [];

return jobs.map(job => ({
  jobId: `remotive_${job.id}`,
  source: 'Remotive',
  title: job.title,
  company: job.company_name,
  url: job.url,
  description: job.description || '',
  isRemote: true,
  postedAt: new Date(job.publication_date).toISOString()
}));

// Normalize RemoteOK API response into common shape
// Note: element [0] is always a legal notice object, skip it
const jobs = Array.isArray($input.first().body) ? $input.first().body : [];

return jobs.slice(1).map(job => ({
  jobId: `remoteok_${job.id || job.slug}`,
  source: 'RemoteOK',
  title: job.position,
  company: job.company,
  url: job.url,
  description: job.description || '',
  isRemote: true,
  postedAt: new Date(job.epoch * 1000).toISOString()
}));

// Normalize Arbeitnow API response into common shape
const jobs = $input.first().body.data || [];

return jobs.map(job => ({
  jobId: `arbeitnow_${job.slug}`,
  source: 'Arbeitnow',
  title: job.title,
  company: job.company_name,
  url: job.url,
  description: job.description || '',
  isRemote: !!job.remote,
  postedAt: new Date(job.created_at).toISOString()
}));

// Filter for remote cloud/DevOps entry-level roles
const KEYWORD_INCLUDE = [
  'cloud engineer', 'associate cloud engineer', 'cloud support engineer',
  'devops engineer', 'site reliability engineer', 'cloud infrastructure engineer',
  'cloud engineer intern', 'entry level', 'junior', 'associate', 'junior cloud',
  'junior devops', 'sre', 'associate devops', 'associate infrastructure',
  'aws', 'azure', 'gcp', 'kubernetes', 'docker'
];

const KEYWORD_EXCLUDE = [
  'senior', 'staff', 'principal', 'lead', 'manager', 'director',
  'head of', 'chief', 'vp ', 'vice president', 'architect'
];

const jobs = $input.first().json;

return jobs.filter(job => {
  // Must be remote
  if (!job.isRemote) return false;

  const titleLower = (job.title || '').toLowerCase();
  const descLower = (job.description || '').toLowerCase();
  const searchText = titleLower + ' ' + descLower;

  // Must match at least one inclusion keyword
  const hasInclude = KEYWORD_INCLUDE.some(kw => searchText.includes(kw));
  if (!hasInclude) return false;

  // Must NOT match any exclusion keyword (seniority filter)
  const hasExclude = KEYWORD_EXCLUDE.some(kw => searchText.includes(kw));
  if (hasExclude) return false;

  return true;
});

// Dedup: keep only jobs not yet seen
const filteredJobs = $input.first().json;
const seenRows = $input.last().json;

// Build a Set of already-seen jobIds
const seenIds = new Set(seenRows.map(row => row.jobId));

// Filter to new jobs only
return filteredJobs.filter(job => !seenIds.has(job.jobId));

